@Slf4j
@PluginDescriptor(
	name = "OSRS Events",
	description = "Auto-completes event tasks on osrs-events.com",
	tags = {"bingo", "clan", "events"}
)
@PluginDependency(LootTrackerPlugin.class)
public class OsrsEventsPlugin extends Plugin
{
	private static final String COLLECTION_LOG_PREFIX = "New item added to your collection log:";
	private static final int MAX_CONTEXT_ITEMS = 40;

	/**
	 * No colours of our own. A fixed colour cannot be readable on both an
	 * opaque black chatbox and a transparent one over a bright world, so every
	 * part of a line uses the player's own chat colours, which RuneLite already
	 * keeps in two variants for exactly that reason. Only the accent is ours,
	 * and it is a setting so it can be tuned against a real chatbox.
	 */
	/** Client ticks (20ms) without mouse or keyboard before the refresh backs off. */
	private static final int IDLE_CLIENT_TICKS = 15_000;
	private static final int IDLE_REFRESH_SECONDS = 600;
	private static final int RETRY_TICKS = 10;
	private static final int MAX_ATTEMPTS = 30;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OsrsEventsConfig config;

	@Inject
	private OsrsEventsApi api;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	private OsrsEventsPanel panel;
	private NavigationButton navButton;

	private volatile Set<String> watch = Collections.emptySet();
	private final ConcurrentLinkedDeque<Pending> queue = new ConcurrentLinkedDeque<>();
	private final AtomicBoolean sending = new AtomicBoolean();
	private volatile boolean rejected;
	/** The OSRS characters on the site account, main first, from the last answer. Empty until known or when the account has none. */
	private volatile List<ApiModels.OsrsCharacter> characters = Collections.emptyList();
	/** The character POST /identity was already sent for since the last login, so a refresh does not repeat it. */
	private volatile String identitySentFor;
	/** Why /identity did not add that character: disabled, limit, taken, or null. */
	private volatile String notAddedReason;
	private int ticks;
	private int retryTicks;
	private final Map<String, Integer> killCounts = new HashMap<>();
	private final Map<String, Integer> killCountTicks = new HashMap<>();
	private final Map<String, Integer> activityTicks = new HashMap<>();
	private final Map<String, Integer> activityCounts = new HashMap<>();
	private boolean loginPending = true;
	/** Logged in, waiting for the local player's name before the first request. */
	private boolean connectPending;
	private final Set<String> seenVerdicts = new HashSet<>();
	private boolean verdictsSeeded;

	private static final class Pending
	{
		final ApiModels.Completion completion;
		int attempts;

		Pending(ApiModels.Completion completion)
		{
			this.completion = completion;
		}
	}

	@Override
	protected void startUp()
	{
		panel = new OsrsEventsPanel(this::checkConnection);
		navButton = NavigationButton.builder()
			.tooltip("OSRS Events")
			.icon(ImageUtil.loadImageResource(getClass(), "panel.png"))
			.priority(10)
			.panel(panel)
			.build();
		if (config.showPanel())
		{
			clientToolbar.addNavigation(navButton);
		}
		showStatus();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loginPending = false;
			connectPending = true;
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		watch = Collections.emptySet();
		queue.clear();
		seenVerdicts.clear();
		killCounts.clear();
		killCountTicks.clear();
		activityTicks.clear();
		activityCounts.clear();
		verdictsSeeded = false;
		rejected = false;
		characters = Collections.emptyList();
		identitySentFor = null;
		notAddedReason = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!OsrsEventsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("checkConnection".equals(event.getKey()))
		{
			if ("true".equals(event.getNewValue()))
			{
				configManager.setConfiguration(OsrsEventsConfig.GROUP, "checkConnection", false);
				checkConnection();
			}
			return;
		}

		if ("showPanel".equals(event.getKey()))
		{
			if (config.showPanel())
			{
				clientToolbar.addNavigation(navButton);
			}
			else
			{
				clientToolbar.removeNavigation(navButton);
			}
			return;
		}

		rejected = false;
		watch = Collections.emptySet();
		characters = Collections.emptyList();
		identitySentFor = null;
		notAddedReason = null;
		showStatus();
		refreshWatch(config.chatStatus());
	}

	/** The config tick box and the panel button: try again now, and say the result in chat. */
	private void checkConnection()
	{
		rejected = false;
		if (!config.enabled())
		{
			chat("Turn on Send completions first.");
		}
		showStatus();
		refreshWatch(true);
	}

	/** What the panel can say before the server has answered. */
	private void showStatus()
	{
		if (!config.enabled())
		{
			panel.setStatus("Send completions is off. Turn it on in the plugin settings.", false);
		}
		else if (!api.isConfigured())
		{
			panel.setStatus("Paste your plugin code in the settings. The Server must start with https://.", false);
		}
		else if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.setStatus("Log in to the game to connect.", null);
		}
		else
		{
			panel.setStatus("Connecting…", true);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			loginPending = true;
			// The next login may be another character.
			identitySentFor = null;
			notAddedReason = null;
			if (state == GameState.LOGIN_SCREEN)
			{
				connectPending = false;
				panel.setCharacter("Not logged in", "");
				showStatus();
			}
		}
		// Loading screens also end in LOGGED_IN; only the first one after a login announces.
		else if (state == GameState.LOGGED_IN && loginPending)
		{
			loginPending = false;
			connectPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// The login announces once the character is known: before that the
		// panel and chat would say "not logged in" to somebody who is.
		Player local = client.getLocalPlayer();
		if (connectPending && local != null && local.getName() != null)
		{
			connectPending = false;
			ticks = 0;
			refreshWatch(config.chatStatus());
		}

		ticks++;
		if (ticks >= refreshEveryTicks())
		{
			ticks = 0;
			refreshWatch(false);
		}
		if (++retryTicks >= RETRY_TICKS)
		{
			retryTicks = 0;
			sendNext();
		}
	}

	/** A game tick is 0.6s; an idle player asks far less often. */
	private int refreshEveryTicks()
	{
		boolean idle = client.getMouseIdleTicks() > IDLE_CLIENT_TICKS && client.getKeyboardIdleTicks() > IDLE_CLIENT_TICKS;
		int seconds = idle ? IDLE_REFRESH_SECONDS : Math.min(Math.max(config.refreshSeconds(), 15), IDLE_REFRESH_SECONDS);

		return (int) Math.ceil(seconds / 0.6);
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		ApiModels.Context context = context("npc_kill", npc, event.getItems());

		if (npc != null)
		{
			report("npc_kill", npc.getName(), 1, context);
		}
		reportItems(event.getItems(), context);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		// NPC loot already arrives through NpcLootReceived; players are never a source.
		if (event.getType() == LootRecordType.NPC || event.getType() == LootRecordType.PLAYER)
		{
			return;
		}
		String source = event.getName();
		ApiModels.Context context = context("loot", null, event.getItems());
		context.npcName = source;
		context.killCount = killCountFor(String.valueOf(source));

		// The source is a claimable thing in its own right, the same way an
		// NPC is. RuneLite names these events after what was done — the loot
		// tracker's "Herbiboar", "Barrows", "Guardians of the Rift" — so a
		// square asking for the activity rather than one of its drops has
		// something to match. A name nothing watches is dropped anyway.
		report("npc_kill", source, 1, context);

		reportItems(event.getItems(), context);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage().replaceAll("<[^>]*>", "");

		KillCount.Parsed killCount = KillCount.parse(message);
		if (killCount != null)
		{
			killCounts.put(NameMatcher.normalize(killCount.name), killCount.count);
			killCountTicks.put(NameMatcher.normalize(killCount.name), client.getTickCount());

			// The only signal a minigame gives: Tempoross and friends drop no loot on
			// the kill itself, so without this nothing would ever claim their square.
			ApiModels.Context context = context("kill_count", null, null);
			context.npcName = killCount.name;
			context.killCount = killCount.count;
			report("npc_kill", killCount.name, 1, context);
			return;
		}

		if (message.startsWith(COLLECTION_LOG_PREFIX))
		{
			report("item", message.substring(COLLECTION_LOG_PREFIX.length()).trim(), 1, context("collection_log", null, null));
		}
	}

	private void reportItems(Collection<ItemStack> items, ApiModels.Context context)
	{
		Map<String, Integer> byName = new LinkedHashMap<>();
		for (ItemStack item : items)
		{
			String name = itemManager.getItemComposition(item.getId()).getName();
			byName.merge(name, item.getQuantity(), Integer::sum);
		}
		byName.forEach((name, quantity) -> report("item", name, quantity, context));
	}

	/**
	 * What a host can judge a claim by: what died, its level, the killcount,
	 * everything else that dropped with it, and the region. Never chat, other
	 * players or exact coordinates.
	 */
	private ApiModels.Context context(String source, NPC npc, Collection<ItemStack> items)
	{
		ApiModels.Context context = new ApiModels.Context();
		context.source = source;

		if (npc != null)
		{
			context.npcId = npc.getId();
			context.npcName = npc.getName();
			context.npcLevel = npc.getCombatLevel();
			context.killCount = killCountFor(npc.getName());
		}

		Player local = client.getLocalPlayer();
		if (local != null && local.getWorldLocation() != null)
		{
			context.regionId = local.getWorldLocation().getRegionID();
		}

		if (items != null)
		{
			context.items = items.stream()
				.limit(MAX_CONTEXT_ITEMS)
				.map(item -> new ApiModels.Item(item.getId(), itemManager.getItemComposition(item.getId()).getName(), Math.max(item.getQuantity(), 1)))
				.collect(Collectors.toList());
		}

		return context;
	}

	/**
	 * The kill count belonging to this event, or null.
	 *
	 * Only a count from the same tick counts as belonging to it. The message
	 * and the loot arrive together, and an older one is the *previous* kill —
	 * attaching it would hand the server a number it has already counted, and
	 * a square asking for five kills would sit still on the second. RuneLite
	 * expires the same association on the same rule.
	 */
	private Integer killCountFor(String name)
	{
		String key = NameMatcher.normalize(name);

		return Integer.valueOf(client.getTickCount()).equals(killCountTicks.get(key)) ? killCounts.get(key) : null;
	}

	/**
	 * Whether this activity has already been reported for the thing that just
	 * happened. One thing done is one report, and two of them do not walk a
	 * counted square two steps.
	 *
	 * The same activity reaches us by two roads and they do not arrive
	 * together:
	 *
	 * - A Herbiboar harvest raises a loot event and a "Your herbiboar harvest
	 *   count is:" message in the **same tick**.
	 * - A Guardians of the Rift game announces the closed rift when the game
	 *   ends, and the reward chest is searched **minutes later** — same
	 *   activity, far apart, so a tick is no help.
	 *
	 * So a report is suppressed when it repeats the tick, or when it repeats
	 * a kill count already reported for that name. The counter moving is what
	 * says another one was done; a second road to the same number is the same
	 * event arriving twice.
	 *
	 * An activity with no counter at all keeps working: nothing to repeat, so
	 * only the tick rule applies.
	 *
	 * Items are deliberately not covered. Two kills in one tick really are two
	 * drops, and dropping the second would lose a report that counts.
	 */
	private boolean reportedAlready(String name)
	{
		String key = NameMatcher.normalize(name);
		int tick = client.getTickCount();
		Integer count = killCounts.get(key);

		boolean sameTick = Integer.valueOf(tick).equals(activityTicks.get(key));
		boolean sameCount = count != null && count.equals(activityCounts.get(key));

		if (sameTick || sameCount)
		{
			return true;
		}

		activityTicks.put(key, tick);
		activityCounts.put(key, count);

		return false;
	}

	private void report(String kind, String name, int quantity, ApiModels.Context context)
	{
		if (!config.enabled() || rejected || !api.isConfigured() || name == null || !watch.contains(NameMatcher.normalize(name)))
		{
			return;
		}

		if ("npc_kill".equals(kind) && reportedAlready(name))
		{
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		// The server refuses a character that is not on the account, so it is not worth a request per drop.
		if (!isAccountCharacter(local.getName(), characters))
		{
			return;
		}

		queue.add(new Pending(new ApiModels.Completion(
			UUID.randomUUID().toString(),
			kind,
			name,
			Math.max(quantity, 1),
			local.getName(),
			Instant.now().toString(),
			context
		)));
		sendNext();
	}

	/** With announce, the result goes to chat: this is the connection check. */
	private void refreshWatch(boolean announce)
	{
		if (!config.enabled() || rejected)
		{
			return;
		}

		if (!api.isConfigured())
		{
			if (announce)
			{
				chat("Paste your plugin code and check the Server setting. It must start with https://.");
			}
			return;
		}

		api.fetchEvents((status, body) ->
		{
			if (status == 200)
			{
				ApiModels.EventsResponse events = api.parse(body, ApiModels.EventsResponse.class);
				watch = events == null || events.watch == null ? Collections.emptySet() : new HashSet<>(events.watch);
				characters = charactersOf(events);
				log.debug("osrs-events watching {} names", watch.size());
				panel.setStatus("Connected to " + config.serverUrl().trim() + ".", true);
				panel.setEvents(events == null ? null : events.events, events == null ? null : events.otherEvents);
				panel.setRaces(events == null ? null : events.races, events == null ? null : events.otherEvents);
				if (events != null)
				{
					announceVerdicts(events.reviews);
					identify(events, announce);
				}
				return;
			}

			if (status == 401 || status == 404)
			{
				stop(status, body);
			}

			panel.setEvents(null, null);
			panel.setRaces(null, null);
			panel.setStatus(status == 401 ? "The plugin code was not recognised. Create a new one in your settings on the site."
				: status == 404 ? "The plugin is switched off on " + config.serverUrl().trim() + "."
				: status == -1 ? "No answer from " + config.serverUrl().trim() + "."
				: "The server answered " + status + ".", false);

			if (announce)
			{
				if (status == 404)
				{
					chat("The plugin is switched off on " + config.serverUrl().trim() + ".");
				}
				else if (status == -1)
				{
					chat("No answer from " + config.serverUrl().trim() + ". Is the server running?");
				}
				else if (status != 401)
				{
					chat("The server answered " + status + ".");
				}
			}
		});
	}

	/** The first list after a start is only remembered: old verdicts are not news. */
	private void announceVerdicts(List<ApiModels.Verdict> reviews)
	{
		if (reviews == null)
		{
			return;
		}

		for (ApiModels.Verdict verdict : reviews)
		{
			if (verdict.id == null || !seenVerdicts.add(verdict.id) || !verdictsSeeded)
			{
				continue;
			}

			boolean approved = "APPROVED".equals(verdict.status);
			panel.addRecent(verdict.label == null ? "Your claim" : verdict.label, String.valueOf(verdict.eventTitle),
				approved ? "Approved" : "Rejected", approved ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.PROGRESS_ERROR_COLOR);
			if (!config.chatVerdicts())
			{
				continue;
			}

			chat(line()
				.append(config.accent(), verdict.label == null ? "Your claim" : verdict.label)
				.append(ChatColorType.NORMAL).append(" in ")
				.append(config.accent(), String.valueOf(verdict.eventTitle))
				.append(ChatColorType.NORMAL).append(" was ")
				.append(approved ? config.approvedColour() : config.rejectedColour(), approved ? "approved" : "rejected"));
		}

		verdictsSeeded = true;
	}

	/**
	 * Tell the site which character this client is signed in as, then say so in chat.
	 *
	 * Anybody can type somebody else's name on the site, and nothing there
	 * can tell the difference. This is the one thing a game client knows that
	 * a web form does not, so the site asks for it: a name nobody has ever
	 * played from a client does not get its claims approved automatically.
	 *
	 * A character that is not on the account is sent too: with "Add new
	 * characters as alts" on, the site adds it as an alt, and otherwise its
	 * answer says why not. Sent once per login per character; a proven
	 * character on the account needs nothing.
	 */
	private void identify(ApiModels.EventsResponse events, boolean announce)
	{
		clientThread.invokeLater(() ->
		{
			Player local = client.getLocalPlayer();
			String character = local == null ? null : local.getName();
			ApiModels.OsrsCharacter known = findCharacter(character, characters);
			String sentFor = identitySentFor;

			if (character == null || (known != null && known.proven) || (sentFor != null && sameRsn(character, sentFor)))
			{
				connected(events, character, null, false, announce);
				return;
			}

			identitySentFor = character;
			api.postIdentity(new ApiModels.Identity(character, config.addAlts()), (status, body) ->
			{
				ApiModels.IdentityResponse identity = status == 200 ? api.parse(body, ApiModels.IdentityResponse.class) : null;
				if (identity != null && identity.characters != null)
				{
					characters = identity.characters;
				}
				notAddedReason = identity == null ? null : identity.reason;
				connected(events, character, identity, known != null && identity != null && identity.matched, announce);
			});
		});
	}

	/**
	 * Which of the account's characters this is, in the panel always and in
	 * chat with announce, together with what is watched.
	 *
	 * @param identity the answer to POST /identity when one was sent, else null
	 * @param provedNow whether that answer proved a character that was already on the account
	 */
	private void connected(ApiModels.EventsResponse events, String character, ApiModels.IdentityResponse identity, boolean provedNow, boolean announce)
	{
		List<ApiModels.OsrsCharacter> account = characters;
		String main = mainRsn(account);
		ApiModels.OsrsCharacter current = findCharacter(character, account);
		int maxCharacters = Math.max(events.maxCharacters, account.size());

		showCharacter(character, main, current, maxCharacters, account.size());
		if (!announce)
		{
			return;
		}

		if (main == null)
		{
			chat("Connected, but your account has no OSRS character. Turn on Add new characters as alts and log in again, or set one at " + nameSettingsUrl() + ".");
			return;
		}

		if (character != null && current == null)
		{
			// Said once, at login. After that the plugin stays quiet: drops from this character are not sent.
			if (config.chatOtherCharacter())
			{
				chat("You are logged in as " + character + ", which is not on your account. Drops from it are not sent. "
					+ whyNotAdded(notAddedReason, maxCharacters));
			}
			return;
		}

		if (identity != null && identity.added)
		{
			chat(current == null || current.main
				? "Added " + character + " to your account."
				: "Added " + character + " to your account as an alt of " + main + ". Its drops count like the main's.");
		}
		else if (provedNow)
		{
			chat("Your name " + character + " is now proven. Claims from it can be approved without a host checking them.");
		}

		String as = current == null || current.main ? main : current.rsn + " (alt of " + main + ")";
		long eventCount = events.events == null ? 0 : events.events.stream().filter(e -> e.targets != null && !e.targets.isEmpty()).count();

		if (watch.isEmpty())
		{
			chat("Connected as " + as + ". Nothing to watch yet: " + (events.events == null ? 0 : events.events.size()) + " running events, none with an open wiki-linked square or tile.");
		}
		else
		{
			chat("Connected as " + as + ". Watching " + watch.size() + " names in " + eventCount + (eventCount == 1 ? " event." : " events."));
		}
	}

	private void showCharacter(String character, String main, ApiModels.OsrsCharacter current, int maxCharacters, int held)
	{
		if (character == null)
		{
			panel.setCharacter("Not logged in", "");
		}
		else if (main == null)
		{
			panel.setCharacter(character, "Your account has no OSRS character yet. Drops are not sent.");
		}
		else if (current == null)
		{
			panel.setCharacter(character, "Not on your account, so drops are not sent. " + whyNotAdded(notAddedReason, maxCharacters));
		}
		else
		{
			panel.setCharacter(character, (current.main ? "Main" : "Alt of " + main)
				+ (current.proven ? "" : ", not proven yet")
				+ ". Your account holds " + held + " of " + maxCharacters + " characters.");
		}
	}

	/** The rest of the line for a character that is not on the account, from the reason /identity gave. */
	private String whyNotAdded(String reason, int maxCharacters)
	{
		if ("disabled".equals(reason))
		{
			return "Turn on Add new characters as alts to add it, or add it at " + nameSettingsUrl() + ".";
		}
		if ("limit".equals(reason))
		{
			return "Your account already holds " + maxCharacters + " characters, the most it can. Remove one at " + nameSettingsUrl() + " to make room.";
		}
		if ("taken".equals(reason))
		{
			return "Another account has already proven this name.";
		}

		return "Add it at " + nameSettingsUrl() + ".";
	}

	/** Where a player sets the OSRS name on the site. */
	private String nameSettingsUrl()
	{
		HttpUrl base = OsrsEventsApi.baseUrl(config.serverUrl());

		return base == null ? "the site" : base.resolve("/settings/connections").toString();
	}

	/** The account's characters, main first. A server that predates alts only sends the main's rsn and proven. */
	static List<ApiModels.OsrsCharacter> charactersOf(ApiModels.EventsResponse events)
	{
		if (events == null)
		{
			return Collections.emptyList();
		}
		if (events.characters != null)
		{
			return events.characters;
		}
		if (events.rsn == null || events.rsn.isEmpty())
		{
			return Collections.emptyList();
		}

		ApiModels.OsrsCharacter main = new ApiModels.OsrsCharacter();
		main.rsn = events.rsn;
		main.main = true;
		main.proven = events.proven;

		return Collections.singletonList(main);
	}

	/** This character's entry on the account, or null. */
	static ApiModels.OsrsCharacter findCharacter(String character, List<ApiModels.OsrsCharacter> characters)
	{
		if (character == null || characters == null)
		{
			return null;
		}

		return characters.stream()
			.filter(c -> c.rsn != null && sameRsn(character, c.rsn))
			.findFirst()
			.orElse(null);
	}

	/** Whether this character may report: the main or one of its alts. An account without characters matches nothing. */
	static boolean isAccountCharacter(String character, List<ApiModels.OsrsCharacter> characters)
	{
		return findCharacter(character, characters) != null;
	}

	/** The main's name, or null when the account has no character. */
	static String mainRsn(List<ApiModels.OsrsCharacter> characters)
	{
		return characters.stream()
			.filter(c -> c.main && c.rsn != null)
			.map(c -> c.rsn)
			.findFirst()
			.orElse(null);
	}

	static boolean sameRsn(String a, String b)
	{
		return rsnKey(a).equals(rsnKey(b));
	}

	private static String rsnKey(String rsn)
	{
		return rsn.replaceAll("[\\s_\\-\\u00A0]+", " ").trim().toLowerCase(Locale.ROOT);
	}

	private void sendNext()
	{
		if (!config.enabled() || rejected || !api.isConfigured() || queue.isEmpty() || !sending.compareAndSet(false, true))
		{
			return;
		}

		Pending pending = queue.poll();
		if (pending == null)
		{
			sending.set(false);
			return;
		}

		api.postCompletion(pending.completion, (status, body) ->
		{
			sending.set(false);

			if (status == 200 || status == 201)
			{
				ApiModels.CompletionResponse response = api.parse(body, ApiModels.CompletionResponse.class);
				if (response != null && !response.duplicate)
				{
					// A counted square that moved is news even though it
					// claimed nothing: "Zalcano 2 / 5" rather than silence
					// until the fifth kill.
					if (response.progress != null)
					{
						response.progress.forEach(this::announce);
					}

					if (response.claims != null && !response.claims.isEmpty())
					{
						response.claims.forEach(this::announce);
						refreshWatch(false);
					}

					// After the claims: the square is said first, then what it won.
					if (response.finishes != null)
					{
						response.finishes.forEach(this::announce);
					}
				}
			}
			else if (status == 401 || status == 404)
			{
				stop(status, body);
			}
			else if (status == 422)
			{
				api.message(body, this::chat);
			}
			else if (++pending.attempts < MAX_ATTEMPTS)
			{
				// No answer, rate limited or a server error: keep the same client_event_id and try again later.
				queue.addFirst(pending);
				return;
			}

			sendNext();
		});
	}

	/** 401: the code is wrong until the config changes. 404: the API is off for now; the periodic refresh finds it again. */
	private void stop(int status, String body)
	{
		watch = Collections.emptySet();
		characters = Collections.emptyList();
		queue.clear();

		if (status == 401)
		{
			rejected = true;
			api.message(body, this::chat);
		}
	}

	private void announce(ApiModels.Claim claim)
	{
		boolean pending = "PENDING".equals(claim.status);
		panel.addRecent(claim.label != null ? claim.label : String.valueOf(claim.name), String.valueOf(claim.eventTitle),
			pending ? "Review" : "Claimed", pending ? ColorScheme.BRAND_ORANGE : ColorScheme.PROGRESS_COMPLETE_COLOR);

		if (!config.chatClaims())
		{
			return;
		}

		ChatMessageBuilder message = line()
			.append(ChatColorType.NORMAL).append("Claimed ")
			.append(config.accent(), claim.label != null ? claim.label : claim.name)
			.append(ChatColorType.NORMAL).append(" in ")
			.append(config.accent(), String.valueOf(claim.eventTitle))
			.append(ChatColorType.NORMAL).append(" - ");

		// Only the verdict carries a colour of its own. A claim that counted
		// and a claim still waiting are the one thing worth telling apart at
		// a glance, and the rest of the line stays in the accent so a green
		// word means "done" and nothing else.
		message.append(
			pending ? config.accent() : config.approvedColour(),
			pending ? "waiting for review" : "approved");

		chat(message);
	}

	private void announce(ApiModels.FinishNews finish)
	{
		String place = ordinal(finish.place) + " place";
		panel.addRecent(String.valueOf(finish.eventTitle), String.valueOf(finish.eventTitle),
			ordinal(finish.place), OsrsEventsPanel.GOLD);

		if (!config.chatClaims())
		{
			return;
		}

		ChatMessageBuilder message = line().append(ChatColorType.NORMAL)
			.append(finish.team != null ? "Your team " : "You ");
		if (finish.team != null)
		{
			message.append(config.accent(), finish.team).append(ChatColorType.NORMAL).append(" ");
		}
		message.append("finished ")
			.append(config.accent(), String.valueOf(finish.eventTitle))
			.append(ChatColorType.NORMAL).append(" - ")
			.append(config.approvedColour(), place + "!");
		if (finish.provisional)
		{
			message.append(ChatColorType.NORMAL).append(" For now: claims ahead of yours are still in review.");
		}

		chat(message);
	}

	/** 1st, 2nd, 3rd, 4th, 11th, 21st. */
	static String ordinal(int n)
	{
		int lastTwo = n % 100;
		String suffix = lastTwo >= 11 && lastTwo <= 13 ? "th"
			: n % 10 == 1 ? "st" : n % 10 == 2 ? "nd" : n % 10 == 3 ? "rd" : "th";
		return n + suffix;
	}

	private void announce(ApiModels.Progress progress)
	{
		panel.addRecent(progress.label != null ? progress.label : String.valueOf(progress.name), String.valueOf(progress.eventTitle),
			progress.done + " / " + progress.requiredCount, Color.WHITE);

		if (!config.chatClaims())
		{
			return;
		}

		chat(line()
			.append(config.accent(), progress.label != null ? progress.label : String.valueOf(progress.name))
			.append(ChatColorType.NORMAL).append(" ")
			.append(config.accent(), progress.done + " / " + progress.requiredCount)
			.append(ChatColorType.NORMAL).append(" in ")
			.append(config.accent(), String.valueOf(progress.eventTitle)));
	}

	/** One builder per line: appending an already-built string escapes its tags. */
	private ChatMessageBuilder line()
	{
		return new ChatMessageBuilder().append(config.accent(), "OSRS Events: ");
	}

	private void chat(String text)
	{
		chat(line().append(ChatColorType.NORMAL).append(text));
	}

	private void chat(ChatMessageBuilder message)
	{
		String formatted = message.build();

		clientThread.invokeLater(() -> chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build()));
	}

	@Provides
	OsrsEventsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrsEventsConfig.class);
	}
}

package com.osrsevents;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The "Your X kill count is: N" family of game messages.
 *
 * The wording is not one sentence but several, and guessing at it was wrong
 * twice: the descriptor sits in front of the name as often as behind it
 * ("Your completed Chambers of Xeric count is:", "Your subdued Wintertodt
 * count is:", "Your completion count for Barrows is:"), the middle word is
 * not always "kill" (harvest, lap, completion, success, Total Ticket), and
 * the number can arrive wrapped in an @col@ marker rather than a tag.
 *
 * This mirrors KILLCOUNT_PATTERN in RuneLite's own ChatCommandsPlugin
 * (client 1.12.39), which is maintained against the live game. Do not tighten
 * it from memory — read that file.
 */
final class KillCount
{
	/**
	 * Both halves are optional on their own, and a line with neither is not a
	 * kill count at all — "Your poisoned karambwan is: ..." would otherwise
	 * parse. RuneLite draws the same line for the same reason.
	 */
	/**
	 * Counters that do not use the sentence above at all. Each one is its own
	 * wording in the game, so each one is its own pattern; RuneLite keeps them
	 * apart for the same reason.
	 *
	 * The name is the **wiki page title**, not the name RuneLite files the
	 * count under, because the server matches a report against the title of a
	 * wiki-linked task. Those differ: RuneLite says "Hunter Rumours", the wiki
	 * page is "Hunters' Rumours", and after normalising apostrophes away that
	 * is still "hunter rumours" against "hunters rumours" — a square would
	 * never match.
	 */
	private static final Pattern RUMOURS = Pattern.compile(
		"You have completed (?:@[^@]+@)?(?<count>[0-9,]+) rumours? for the Hunter Guild");

	private static final Pattern RIFTS = Pattern.compile(
		"Amount of Rifts you have closed: (?:@[^@]+@)?(?<count>[0-9,]+)", Pattern.CASE_INSENSITIVE);

	/**
	 * A full run: the coffin is opened once at the end of one. A square that
	 * means "do the Sepulchre N times" means this.
	 */
	private static final Pattern COFFIN = Pattern.compile(
		"You have opened the Grand Hallowed Coffin (?:@[^@]+@)?(?<count>[0-9,]+) times?");

	/**
	 * One floor, counted per floor.
	 *
	 * Every floor carries its **own** total, so naming each floor separately
	 * is what keeps them apart — floor 1 at 50 and floor 5 at 50 are two
	 * different targets, not the same count twice. That makes "run floor 1
	 * twenty times" expressible, which one shared name could never be.
	 *
	 * The reported name is not a wiki page and does not have to be: a task
	 * links a wiki page, but its title is free text, and the title is what a
	 * report is matched against. A square for this carries the title
	 * "Hallowed Sepulchre Floor 1".
	 */
	private static final Pattern FLOOR = Pattern.compile(
		"You have completed Floor (?<floor>[0-9]+) of the Hallowed Sepulchre! "
			+ "Total completions: (?:@[^@]+@)?(?<count>[0-9,]+)");

	private static final Pattern PATTERN = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?<name>.+?) "
			+ "(?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)"
			+ "is: ?(?:@[^@]+@)?(?<count>[0-9,]+)");

	static final class Parsed
	{
		final String name;
		final int count;

		private Parsed(String name, int count)
		{
			this.name = name;
			this.count = count;
		}
	}

	private KillCount()
	{
	}

	/** The message with its tags already stripped, or null when it is not one of these. */
	static Parsed parse(String message)
	{
		Parsed named = named(message);
		if (named != null)
		{
			return named;
		}

		Matcher matcher = PATTERN.matcher(message);

		if (!matcher.find())
		{
			return null;
		}

		String pre = matcher.group("pre");
		String post = matcher.group("post");

		if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
		{
			return null;
		}

		return new Parsed(matcher.group("name"), Integer.parseInt(matcher.group("count").replace(",", "")));
	}

	/** The counters whose wording carries no name, so the name is ours to supply. */
	private static Parsed named(String message)
	{
		Parsed rumours = match(RUMOURS, message, "Hunters' Rumours");
		if (rumours != null)
		{
			return rumours;
		}

		Parsed rifts = match(RIFTS, message, "Guardians of the Rift");
		if (rifts != null)
		{
			return rifts;
		}

		Parsed coffin = match(COFFIN, message, "Grand Hallowed Coffin");
		if (coffin != null)
		{
			return coffin;
		}

		Matcher floor = FLOOR.matcher(message);

		return floor.find()
			? new Parsed("Hallowed Sepulchre Floor " + floor.group("floor"),
				Integer.parseInt(floor.group("count").replace(",", "")))
			: null;
	}

	private static Parsed match(Pattern pattern, String message, String name)
	{
		Matcher matcher = pattern.matcher(message);

		return matcher.find()
			? new Parsed(name, Integer.parseInt(matcher.group("count").replace(",", "")))
			: null;
	}
}

package com.osrsevents;

import com.google.gson.annotations.SerializedName;
import java.util.List;
import lombok.AllArgsConstructor;

final class ApiModels
{
	private ApiModels()
	{
	}

	@AllArgsConstructor
	static class Item
	{
		final int id;
		final String name;
		final int quantity;
	}

	static class Context
	{
		String source;
		@SerializedName("npc_id")
		Integer npcId;
		@SerializedName("npc_name")
		String npcName;
		@SerializedName("npc_level")
		Integer npcLevel;
		@SerializedName("kill_count")
		Integer killCount;
		@SerializedName("region_id")
		Integer regionId;
		List<Item> items;
	}

	@AllArgsConstructor
	static class Completion
	{
		@SerializedName("client_event_id")
		final String clientEventId;
		final String kind;
		final String name;
		final int quantity;
		final String rsn;
		@SerializedName("occurred_at")
		final String occurredAt;
		final Context context;
	}

	/** The character this client is signed in as, for POST /identity. */
	@AllArgsConstructor
	static class Identity
	{
		final String rsn;
		/** Whether the server may add this character to the account as an alt. */
		@SerializedName("add_alt")
		final boolean addAlt;
	}

	static class IdentityResponse
	{
		/** Whether the character is on the account after the call. */
		boolean matched;
		/** Whether this call added it as an alt. */
		boolean added;
		/** Why an unknown character was not added: disabled, limit or taken. */
		String reason;
		List<OsrsCharacter> characters;
	}

	/** One OSRS character on the account. The main comes first. */
	static class OsrsCharacter
	{
		String rsn;
		boolean main;
		boolean proven;
	}

	static class EventsResponse
	{
		String mode;
		String rsn;
		/** Whether a client has ever reported this account playing `rsn`. */
		boolean proven;
		/** Every character the account may report from, main first. Null from a server that predates alts. */
		List<OsrsCharacter> characters;
		@SerializedName("max_characters")
		int maxCharacters;
		List<EventInfo> events;
		/** Running races the account is in. Null from a server that predates them. */
		List<Race> races;
		/** Null from a server that predates it. */
		@SerializedName("other_events")
		List<OtherEvent> otherEvents;
		List<Verdict> reviews;
		List<String> watch;
	}

	static class EventInfo
	{
		String id;
		String title;
		/** BINGO or SNAKES_LADDERS. */
		String type;
		String url;
		List<Target> targets;
		/** The account's (or its team's) finish, null when it has not finished. */
		Finish finish;
	}

	/** A place on an event's podium. */
	static class Finish
	{
		int place;
		/** Claims ahead of it are still in review, so the place can still change. */
		boolean provisional;
		/** The team that finished, null for a solo event. */
		String team;
	}

	/** A finish a report just caused, from POST /completions. */
	static class FinishNews extends Finish
	{
		@SerializedName("event_id")
		String eventId;
		@SerializedName("event_title")
		String eventTitle;
	}

	/** An event the account plays that is not running: upcoming, paused, or ended in the last week. */
	static class OtherEvent
	{
		String id;
		String title;
		/** BINGO, SNAKES_LADDERS, DROP_RACE or SKILL_RACE. */
		String type;
		String url;
		/** upcoming, paused or ended. */
		String status;
		@SerializedName("starts_at")
		String startsAt;
		@SerializedName("ends_at")
		String endsAt;
		/** Bingo and snakes & ladders only. */
		Finish finish;
		/** Races only. */
		Integer rank;
		Integer entrants;

		boolean isRace()
		{
			return "DROP_RACE".equals(type) || "SKILL_RACE".equals(type);
		}
	}

	/** A drop or skill race and where the account stands in it: its best character, as the race page shows. */
	static class Race
	{
		String id;
		String title;
		/** DROP_RACE or SKILL_RACE. */
		String type;
		String url;
		/** The boss or skill, as a label. */
		String metric;
		/** kills or xp. */
		String unit;
		/** Null while nothing has been measured. */
		Integer rank;
		int entrants;
		long gained;
		long live;
		/** Gained of rank 1; null when nobody is ranked. */
		Long leader;
		@SerializedName("ends_at")
		String endsAt;
	}

	/** A square or tile the plugin can complete right now. */
	static class Target
	{
		/** bingo_square, or a board tile. */
		String kind;
		int position;
		String label;
		String name;
		@SerializedName("min_quantity")
		int minQuantity;
		@SerializedName("required_count")
		int requiredCount;
	}

	static class Verdict
	{
		String id;
		String label;
		@SerializedName("event_title")
		String eventTitle;
		String status;
	}

	static class CompletionResponse
	{
		boolean duplicate;
		List<Claim> claims;
		/** Counted targets this report moved without claiming: "2 / 5". */
		List<Progress> progress;
		/** Events this report made the account (or its team) finish. */
		List<FinishNews> finishes;
	}

	static class Progress
	{
		@SerializedName("event_title")
		String eventTitle;
		String label;
		String name;
		int done;
		@SerializedName("required_count")
		int requiredCount;
	}

	static class Claim
	{
		@SerializedName("event_title")
		String eventTitle;
		String label;
		String name;
		String status;
	}

	static class ErrorResponse
	{
		String message;
	}
}

package com.osrsevents;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** The osrs-events plugin API. Every call is enqueued; callbacks run on the OkHttp pool. */
@Slf4j
@Singleton
class OsrsEventsApi
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/**
	 * Sent with every request so the server can tell which build a report came
	 * from. Kept in step with runelite-plugin.properties by a test: the Plugin
	 * Hub builds with its own build file, so nothing can fill it in at build time.
	 */
	static final String VERSION = "0.0.3";

	/** status is -1 when the request never got an answer. */
	interface Result
	{
		void done(int status, String body);
	}

	@Inject
	private OkHttpClient http;

	@Inject
	private Gson gson;

	@Inject
	private OsrsEventsConfig config;

	/**
	 * The plugin code goes in a header, so it only ever travels over https.
	 * The one exception is http to 127.0.0.1: that never leaves the machine,
	 * and it is how a local development server is reached. Anything else is
	 * not a server.
	 */
	static HttpUrl baseUrl(String serverUrl)
	{
		HttpUrl url = HttpUrl.parse(serverUrl.trim());

		return url != null && (url.isHttps() || "127.0.0.1".equals(url.host())) ? url : null;
	}

	boolean isConfigured()
	{
		return !config.token().trim().isEmpty() && baseUrl(config.serverUrl()) != null;
	}

	void fetchEvents(Result result)
	{
		Request request = request("events");
		if (request == null)
		{
			return;
		}
		send(request.newBuilder().get().build(), result);
	}

	void postCompletion(ApiModels.Completion completion, Result result)
	{
		Request request = request("completions");
		if (request == null)
		{
			result.done(-1, null);
			return;
		}
		send(request.newBuilder().post(RequestBody.create(JSON, gson.toJson(completion))).build(), result);
	}

	void postIdentity(ApiModels.Identity identity, Result result)
	{
		Request request = request("identity");
		if (request == null)
		{
			result.done(-1, null);
			return;
		}
		send(request.newBuilder().post(RequestBody.create(JSON, gson.toJson(identity))).build(), result);
	}

	<T> T parse(String body, Class<T> type)
	{
		try
		{
			return gson.fromJson(body, type);
		}
		catch (JsonParseException e)
		{
			log.debug("Unreadable response from osrs-events", e);
			return null;
		}
	}

	void message(String body, Consumer<String> onMessage)
	{
		ApiModels.ErrorResponse error = parse(body, ApiModels.ErrorResponse.class);
		if (error != null && error.message != null)
		{
			onMessage.accept(error.message);
		}
	}

	private Request request(String path)
	{
		String token = config.token().trim();
		HttpUrl base = baseUrl(config.serverUrl());
		if (token.isEmpty() || base == null)
		{
			return null;
		}

		HttpUrl url = base.newBuilder()
			.addPathSegments("api/plugin/v1")
			.addPathSegment(path)
			.build();

		return new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + token)
			.header("Accept", "application/json")
			.header("X-Plugin-Version", VERSION)
			.build();
	}

	private void send(Request request, Result result)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("osrs-events request failed", e);
				result.done(-1, null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					result.done(response.code(), body == null ? null : body.string());
				}
				catch (IOException e)
				{
					log.debug("osrs-events response unreadable", e);
					result.done(-1, null);
				}
			}
		});
	}
}
